/**
 * Typed route map generated by `nestvexa routes:types` from the controllers
 * in the source root (static inspection: routes registered at runtime, global
 * prefixes and versions are not included). Do not edit; rerun the command
 * after changing routes. It imports nothing, so server code and every
 * frontend root can use it. Names follow `routesFromControllers`.
 */
export const routes = {
  'AppController.getHello': { method: 'GET', path: '/' },
  'NestvexaWelcomeController.index': { method: 'GET', path: '/nestvexa' },
  'HomeController.index': { method: 'GET', path: '/home' },
  'ReactDashboardController.index': { method: 'GET', path: '/react-dashboard' },
  'ReactWelcomeController.index': { method: 'GET', path: '/react' },
  'ReportEjsController.index': { method: 'GET', path: '/report-ejs' },
  'ReportNunjucksController.index': { method: 'GET', path: '/report-nunjucks' },
  'ReportPugController.index': { method: 'GET', path: '/report-pug' },
  'SvelteDashboardController.index': {
    method: 'GET',
    path: '/svelte-dashboard',
  },
  'SvelteWelcomeController.index': { method: 'GET', path: '/svelte' },
  'VueDashboardController.index': { method: 'GET', path: '/vue-dashboard' },
  'VueWelcomeController.index': { method: 'GET', path: '/vue' },
  'TaskController.list': { method: 'GET', path: '/task' },
  'TaskController.show': { method: 'GET', path: '/task/:id' },
  'TaskController.create': { method: 'POST', path: '/task' },
  'TaskController.update': { method: 'PATCH', path: '/task/:id' },
  'TaskController.remove': { method: 'DELETE', path: '/task/:id' },
} as const;

export type RouteName = keyof typeof routes;
export type RouteValue = string | number;
type QueryValue = string | number | boolean | null | undefined;
export type RouteQuery = Readonly<
  Record<string, QueryValue | readonly QueryValue[]>
>;
/** Path parameters of each route. Other keys become the query string. */
export type RouteParams = {
  'AppController.getHello': Record<never, never>;
  'NestvexaWelcomeController.index': Record<never, never>;
  'HomeController.index': Record<never, never>;
  'ReactDashboardController.index': Record<never, never>;
  'ReactWelcomeController.index': Record<never, never>;
  'ReportEjsController.index': Record<never, never>;
  'ReportNunjucksController.index': Record<never, never>;
  'ReportPugController.index': Record<never, never>;
  'SvelteDashboardController.index': Record<never, never>;
  'SvelteWelcomeController.index': Record<never, never>;
  'VueDashboardController.index': Record<never, never>;
  'VueWelcomeController.index': Record<never, never>;
  'TaskController.list': Record<never, never>;
  'TaskController.show': { readonly id: RouteValue };
  'TaskController.create': Record<never, never>;
  'TaskController.update': { readonly id: RouteValue };
  'TaskController.remove': { readonly id: RouteValue };
};
/** `params` is optional when the route has no required path parameter. */
export type RouteArgs<Name extends RouteName> =
  Record<never, never> extends RouteParams[Name]
    ? [params?: RouteParams[Name] & RouteQuery]
    : [params: RouteParams[Name] & RouteQuery];

const routeNames: ReadonlySet<string> = new Set(Object.keys(routes));
/** Narrows a string (for example view data) to a known route name. */
export function isRouteName(name: string): name is RouteName {
  return routeNames.has(name);
}

function segment(name: string, key: string, value: unknown): string {
  const text =
    typeof value === 'number' && Number.isFinite(value)
      ? String(value)
      : typeof value === 'string'
        ? value
        : undefined;
  // "." and ".." would be normalized by browsers into another route.
  if (text === undefined || text === '' || text === '.' || text === '..')
    throw new TypeError(
      `Route ${name} needs a string or number for parameter ${key}`,
    );
  return encodeURIComponent(text);
}
function expand(
  name: string,
  pattern: string,
  params: Readonly<Record<string, unknown>>,
  used: Set<string>,
): string {
  return pattern.replace(
    /\{([^}]*)\}|([:*])([A-Za-z_$][\w$]*)/g,
    (
      match,
      group: string | undefined,
      kind: string | undefined,
      key: string | undefined,
    ) => {
      if (group !== undefined) {
        const keys = [...group.matchAll(/[:*]([A-Za-z_$][\w$]*)/g)].map(
          (found) => found[1] ?? '',
        );
        for (const item of keys) used.add(item);
        const present = keys.every(
          (item) =>
            params[item] !== undefined &&
            params[item] !== null &&
            params[item] !== '',
        );
        return present ? expand(name, group, params, used) : '';
      }
      const id = key ?? '';
      used.add(id);
      const value = Object.hasOwn(params, id) ? params[id] : undefined;
      if (kind !== '*') return segment(name, id, value);
      const items: readonly unknown[] = Array.isArray(value)
        ? value
        : typeof value === 'string'
          ? value.split('/')
          : [value];
      return items.map((item) => segment(name, id, item)).join('/');
    },
  );
}

/**
 * URL of a named route. Path parameters are percent-encoded per segment;
 * unused parameters become the query string (undefined and null are skipped).
 * Same rules as `RouteTable#url` in `@nestvexa/views`.
 */
export function route<Name extends RouteName>(
  name: Name,
  ...[params]: RouteArgs<Name>
): string {
  if (!isRouteName(name)) throw new TypeError(`Unknown route: ${String(name)}`);
  const values: Readonly<Record<string, unknown>> = params ?? {};
  const used = new Set<string>();
  const pathname = expand(name, routes[name].path, values, used);
  const query = new URLSearchParams();
  for (const key of Object.keys(values).sort()) {
    const item = values[key];
    if (
      used.has(key) ||
      key === '__proto__' ||
      item === undefined ||
      item === null
    )
      continue;
    for (const entry of Array.isArray(item) ? item : [item]) {
      if (
        typeof entry !== 'string' &&
        typeof entry !== 'boolean' &&
        !(typeof entry === 'number' && Number.isFinite(entry))
      )
        throw new TypeError(
          `Route ${name} query parameter ${key} must be a string, number or boolean`,
        );
      query.append(key, String(entry));
    }
  }
  const search = query.toString();
  return search ? `${pathname}?${search}` : pathname;
}

/**
 * `{ href, method }` for Inertia's `Link` in every framework:
 * `<Link {...routeLink('TaskController.list')}>` (React, Svelte) or
 * `<Link v-bind="routeLink('TaskController.list')">` (Vue). Use `as="button"`
 * for routes that are not GET.
 */
export function routeLink<Name extends RouteName>(
  name: Name,
  ...args: RouteArgs<Name>
): {
  readonly href: string;
  readonly method: Lowercase<(typeof routes)[Name]['method']>;
} {
  const method = routes[name].method.toLowerCase() as Lowercase<
    (typeof routes)[Name]['method']
  >;
  return { href: route(name, ...args), method };
}
